<?php
/** Customer-owned saved order data; never design fixtures. @version 4.4.0 */
defined( 'ABSPATH' ) || exit; ?>
<section id="dashboard"><h2>سلام، <?php echo esc_html( $current_user->display_name ); ?></h2><p class="account-lead">از اینجا سفارش‌ها و اطلاعات حسابت را مدیریت کن.</p>
<div class="account-shortcuts"><a href="<?php echo esc_url( wc_get_account_endpoint_url( 'orders' ) ); ?>"><h3>سفارش‌ها</h3><p>وضعیت و جزئیات سفارش‌هایت را ببین.</p><span>دیدن سفارش‌ها ←</span></a><a href="<?php echo esc_url( wc_get_account_endpoint_url( 'edit-address' ) ); ?>"><h3>نشانی‌ها</h3><p>نشانی ارسال و صورتحساب را مدیریت کن.</p><span>مدیریت نشانی‌ها ←</span></a></div>
<div class="account-orders-heading"><h3>سفارش‌های اخیر</h3><a href="<?php echo esc_url( wc_get_account_endpoint_url( 'orders' ) ); ?>">دیدن همهٔ سفارش‌ها</a></div>
<?php try { $orders = wc_get_orders( array( 'customer_id' => get_current_user_id(), 'limit' => 1, 'orderby' => 'date', 'order' => 'DESC' ) ); } catch ( Exception $error ) { $orders = null; } ?>
<?php if ( null === $orders ) : ?><div class="account-state error-state">سفارش‌ها بارگذاری نشدند؛ <a href="<?php echo esc_url( wc_get_page_permalink( 'myaccount' ) ); ?>">دوباره تلاش کن</a></div>
<?php elseif ( ! $orders ) : ?><div class="account-state"><h3>هنوز سفارشی ثبت نکرده‌ای</h3><p>انتخاب‌های تازه را در فروشگاه ببین.</p><a class="btn" href="<?php echo esc_url( wc_get_page_permalink( 'shop' ) ); ?>">دیدن فروشگاه</a></div>
<?php else : $order = $orders[0]; if ( current_user_can( 'view_order', $order->get_id() ) ) : ?>
<div class="account-order-card"><table class="account-order-table"><thead><tr><th>شماره سفارش</th><th>تاریخ</th><th>وضعیت</th><th>مبلغ سفارش</th></tr></thead><tbody><tr><td data-label="شماره سفارش"><?php echo elinstyle_price_markup( esc_html( $order->get_order_number() ) ); ?></td><td data-label="تاریخ"><?php echo esc_html( wc_format_datetime( $order->get_date_created() ) ); ?></td><td data-label="وضعیت"><span class="pending-badge"><?php echo esc_html( wc_get_order_status_name( $order->get_status() ) ); ?></span></td><td data-label="مبلغ سفارش"><?php echo elinstyle_price_markup( $order->get_formatted_order_total() ); ?></td></tr></tbody></table>
<div class="account-order-actions"><?php foreach ( wc_get_account_orders_actions( $order ) as $key => $action ) : ?><a <?php if ( 'pay' === $key ) { echo 'class="account-pay"'; } ?> href="<?php echo esc_url( $action['url'] ); ?>"><?php echo esc_html( $action['name'] ); ?></a><?php endforeach; ?></div>
<?php $items = $order->get_items(); $item = reset( $items ); if ( $item ) : $product = $item->get_product(); ?><div class="account-order-item"><?php if ( $product ) { echo wp_kses_post( $product->get_image( 'woocommerce_thumbnail' ) ); } ?><div><h3><?php echo esc_html( $item->get_name() ); ?></h3><p><?php echo wp_kses_post( wc_display_item_meta( $item, array( 'echo' => false ) ) ); ?> <?php echo esc_html( elinstyle_catalog_number( $item->get_quantity() ) ); ?> عدد</p></div><small><?php echo elinstyle_price_markup( $order->get_formatted_line_subtotal( $item ) ); ?></small></div><?php endif; ?></div>
<?php endif; endif; ?>
<div class="account-help"><div><h3>دربارهٔ سفارشت پرسشی داری؟</h3><p>شمارهٔ سفارش را در پیام بنویس.</p></div><a href="<?php echo esc_url( home_url( '/contact/' ) ); ?>">تماس با ما</a></div></section>
<?php do_action( 'woocommerce_account_dashboard' ); do_action( 'woocommerce_before_my_account' ); do_action( 'woocommerce_after_my_account' ); ?>
